{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative (sentiment < 0) or shows early signs of decline.",
    "Reduce forecast peaks after sharp spikes — model tends to overreact and overshoots.",
    "Apply mean reversion bias: if price is above 70, reduce forecast by 1-2% per day; if below 60, increase by 1-2% per day.",
    "Lag correction: if true outcome is significantly lower than forecast, reduce next-day forecast by 5-10% to account for delayed market reaction.",
    "When sentiment is neutral (0.00), use 3-day moving average of recent prices to anchor forecast, avoiding overconfidence in short-term spikes."
  ]
}
